  MODE_SPEED: { 2: 1.3, 3: 1.3 }, // v702 (Mickey: "mais 20%, quero mais dinâmico"): 1,1 → 1,3 · v701: 1,1 · v698: 1,3 // v698 (Mickey: 2×2 e 3×3 muito devagar, +30%). Mesmo esquema do X1.speed: a partida anda mais rápido, o relógio não
  X1: { mercy: true, /* v693 (Mickey): 4 gols de vantagem também encerram o 1×1 */ fol: { run: 1.2, runR: 0.8, drib: 4, shot: 8, push: 4, blade: 7, rec: 10, low: 30, lowPen: 3, lowRun: 0.85 },
    speed: 1.31, // v688 (Mickey: 1×1 monótono, +0,25 na velocidade; era 1,06) // v565 (Mickey): 8% mais lento que a v563 (1,15 × 0,92) · v563: X1 15% mais rápido (o relógio compensa, a duração não muda)
    // v563: chute só com shotMin stacks e a menos de shotDist px do gol; sem isso vai para cima do marcador (carry × faceK; perto do gol, turnX, volta para driblar)
    style: { shotMin: 1, /* v693 (Mickey): 1 drible já libera o chute · v654: 5 → 2 */ shotDist: 330, faceK: 1.6, turnX: 260, drib: 1, humilN: 2, humil: ["CANETA!", "CHAPÉU!", "ROLETA!", "LAMBRETA!"], push: 1, blade: 2, max: 12, per: 8, maxGoal: 1 /* v654 (Mickey): gol sempre vale 1 (sem gol x2 com stack) */ },
    push: { w: 0.4, minFol: 30, minGoal: 300, front: 110, dist: [150, 210], speed: 330, cd: 1.6 },
    blade: { w: 3, minFol: 30, near: 100, over: 80, speed: 360, cd: 1.6 }, // v564: blade 2× mais
    // v564 (Mickey): caneta (bola entre as pernas) e drible da vaca (bola por um lado, ele pelo outro); a bola sai do pé e só conta se ele pegar de volta.
    // sucesso = chance do duelo × edge: o marcador fica stun s no chão e não pega a bola por ignore s; senão ele pode cortar a bola
    shotGo: 0.5, // v565: 50% · v564: com 3 stacks e perto do gol, 60% das decisões já viram chute (mais chutes)
    atk: 1.8, // v564: chance de drible no duelo do X1 × 1,8
    chain: [1, 0.9, 0.8, 0.7], // v564: no X1 os dribles seguidos perdem pouca chance (fora do X1 vale IVX.dribChain)
    trick: { caneta: 6, vaca: 5.5, puxada: 2.5, puxEdge: 1.1, back: 70, backSide: 70, backSpeed: 230, minFol: 15, near: 80, behind: 35, side: 45, speed: 250, edge: 1.6, ignore: 0.9, stun: 0.3, cd: 0.4, react: 0.04 },
    // v565 (Mickey): combos: depois de um truque que deu certo, por win s os truques pesam × k e entra o haxball (hax); truques pegos a menos de chain s um do outro = COMBO xN (+stack)
    tackle: { speed: [220, 320], spread: 0.35, stun: 0.8, self: 0.15 }, // v567 (Mickey): desarme no X1 espirra a bola para o lado oposto do bote (speed px/s, spread rad); quem tomou fica stun 0,8 s; quem deu, self s
    hax: { w: 1.2, near: 160, errK: 0.45, drib: 0.9, chain: 0.8, wall: 120, again: 8, backX: 400, backY: 0, backW: 3 }, // v570: chain × Passe/31 de emendar outro haxball perto da parede (a menos de wall px), again = peso; backboard no X1 a menos de backX px da linha de fundo
    boost: 1.0, // v570 (Mickey): segundos de arrancada (× 1,25 velocidade) depois de cada drible no X1 // v567 (Mickey): haxball no X1 com o marcador na frente (w, near), erro × errK (fácil mesmo com Passe baixo), chance drib × Passe/31 de já emendar um drible
    // v568 (Mickey): cook = sem fôlego (< fol) ele anda (walk × velocidade, recupera), chama o bote ("VEM!") e tira no último segundo (dodge × (0,4 + Drible/31), marcador stun s); sai com fol + hyst
    cook: { fol: 45, hyst: 20, walk: 0.35, dodge: 0.55, flairK: 0.8, stun: 0.6, cost: 2, trickK: 0.3 },
    // v568 (Mickey): firula: depois de driblar, chance k × (Drible/31)^pow de voltar para cima do marcador batido por t s (walk × velocidade); Drible baixo joga o arroz com feijão
    flair: { k: 0.7, pow: 2, t: [0.8, 1.6], walk: 0.6 },
    combo: { win: 1.4, chain: 2.6, k: 1.6, hax: 3, minFol: 15, stack: 1, blade2: 0.6 }, // v570: blade2 × Drible/31 = chance de emendar outro blade
    mood: [0.4, 1.6], // v565: cada jogador sorteia, por partida, um peso para cada truque (X1 mais aleatório)
    xp: { goalK: 0.3, drib: 0.8 } },
